//! Emits the CPython table this crate publishes, parsed from
//! `packaging/languages.tsv` at build time (`MB.67.3`).
//!
//! One declaration, one reader: the file's `python` rows become
//! `SUPPORTED_MINORS` (minor numbers, newest first), `DEFAULT_MINOR` (the newest
//! dotted release the refusals tell a developer to install), the
//! `supported_minors_sentence()` helper, one `PY_MINOR_<digits>` constant and
//! one `py_slug` arm per declared minor. The shim file name is built from the
//! row's `slug` column, never a re-spelling of the version. The generated file is
//! `include!`d by `src/lib.rs`; the freshness test parses the same TSV with the
//! same fragment and asserts the emitted values equal it.

include!("../../packaging/languages.rs.inc");

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

fn main() {
    let root = workspace_root();
    let tsv = root.join("packaging/languages.tsv");
    let inc = root.join("packaging/languages.rs.inc");
    println!("cargo:rerun-if-changed={}", absolute(&tsv));
    println!("cargo:rerun-if-changed={}", absolute(&inc));
    println!("cargo:rerun-if-changed=build.rs");

    let rows = load(&tsv).unwrap_or_else(|err| panic!("blastit-py-sapi: {err}"));
    let python = rows_of(&rows, "python");
    if python.is_empty() {
        panic!(
            "blastit-py-sapi: {} declares no python row, so no shim can be named",
            tsv.display()
        );
    }
    let out_dir =
        std::env::var("OUT_DIR").unwrap_or_else(|_| panic!("blastit-py-sapi: cargo sets OUT_DIR"));
    let path = Path::new(&out_dir).join("languages.rs");
    std::fs::write(&path, emit(&python))
        .unwrap_or_else(|err| panic!("blastit-py-sapi: cannot write {}: {err}", path.display()));
}

/// The repository root, two directories above this crate.
fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| panic!("blastit-py-sapi: build.rs has no workspace root"))
}

/// The absolute spelling of `path`, for `cargo:rerun-if-changed`.
fn absolute(path: &Path) -> String {
    std::fs::canonicalize(path).map_or_else(
        |_| path.display().to_string(),
        |resolved| resolved.display().to_string(),
    )
}

/// The generated `$OUT_DIR/languages.rs`, included by `src/lib.rs`.
fn emit(python: &[&Row]) -> String {
    let mut out = String::new();
    out.push_str("// @generated by build.rs from packaging/languages.tsv. Do not edit.\n\n");

    out.push_str("/// CPython minors a WSGI view may be served by, newest first.\n");
    let _ = writeln!(
        out,
        "pub const SUPPORTED_MINORS: [u32; {}] = [{}];\n",
        python.len(),
        python
            .iter()
            .map(|row| minor(&row.version).to_string())
            .collect::<Vec<String>>()
            .join(", ")
    );

    out.push_str("/// The CPython release the refusals tell a developer to install.\n");
    let _ = writeln!(
        out,
        "pub const DEFAULT_MINOR: &str = {};\n",
        quote(&python[0].version)
    );

    out.push_str("/// [`DEFAULT_MINOR`], as one value a format string can name.\n#[must_use]\npub fn default_minor() -> &'static str {\n    DEFAULT_MINOR\n}\n\n");

    let ordered: Vec<&str> = python.iter().map(|row| row.version.as_str()).collect();
    out.push_str("/// The declared CPython minors as one sentence (`CPython 3.13 and 3.14`).\n");
    let _ = writeln!(
        out,
        "pub const SUPPORTED_MINORS_SENTENCE: &str = {};\n",
        quote(&sentence("CPython", &ascending(&ordered)))
    );

    out.push_str("/// [`SUPPORTED_MINORS_SENTENCE`].\n#[must_use]\npub fn supported_minors_sentence() -> &'static str {\n    SUPPORTED_MINORS_SENTENCE\n}\n");

    for row in python {
        let digits = row.digits();
        let _ = writeln!(
            out,
            "\n/// CPython {} as a shim reports it through `py_minor`.\npub const PY_MINOR_{digits}: u32 = crate::abi::encode_py_minor({}, {});",
            row.version,
            major(&row.version),
            minor(&row.version)
        );
    }

    out.push_str("\n/// The `slug` column for one declared CPython minor: the\n/// `libblastit_<slug>` infix of the shim file name.\n");
    out.push_str("pub const fn py_slug(minor: u32) -> Option<&'static str> {\n    match minor {\n");
    for row in python {
        let _ = writeln!(
            out,
            "        {} => Some({}),",
            minor(&row.version),
            quote(row.slug())
        );
    }
    out.push_str("        _ => None,\n    }\n}\n");

    out
}

/// A Rust string literal for `value`.
fn quote(value: &str) -> String {
    format!("{value:?}")
}

/// The major of `"3.13"` (`3`).
fn major(version: &str) -> u32 {
    version
        .split_once('.')
        .unwrap_or_else(|| panic!("packaging/languages.rs.inc parsed a version without a dot"))
        .0
        .parse()
        .unwrap_or_else(|_| panic!("packaging/languages.rs.inc parsed a non-numeric major"))
}

/// The minor of `"3.13"` (`13`).
fn minor(version: &str) -> u32 {
    version
        .split_once('.')
        .unwrap_or_else(|| panic!("packaging/languages.rs.inc parsed a version without a dot"))
        .1
        .parse()
        .unwrap_or_else(|_| panic!("packaging/languages.rs.inc parsed a non-numeric minor"))
}
